from types import SimpleNamespace as NS


def owned_replica_sets(replica_sets, deployment):
    """Keep only the ReplicaSets this Deployment controls."""
    uid = getattr(deployment.metadata, "uid", None)
    name = deployment.metadata.name
    owned = []
    for rs in replica_sets:
        for ref in (rs.metadata.owner_references or []):
            if not getattr(ref, "controller", False) or ref.kind != "Deployment":
                continue
            if uid and getattr(ref, "uid", None):
                if ref.uid == uid:
                    owned.append(rs)
                    break
            elif ref.name == name:
                owned.append(rs)
                break
    return owned
